      stop(); if (ev.error === 'aborted') return;
      ffPushMsg('err', ({ 'not-allowed': 'محتاج إذن استخدام الميكروفون من المتصفح.', 'audio-capture': 'مفيش ميكروفون متاح.' })[ev.error] || 'تعذّر التعرف على الصوت: ' + ev.error);
