  if (prior) v = v.replace(new RegExp(`^\\s*(['"]?)${prior.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}\\1\\s*,\\s*`, 'i'), '');
  if (font && !new RegExp(`^\\s*(['"]?)${font.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}\\1\\s*(,|$)`, 'i').test(v)) v = `${ffidQuoteFont(font)}, ${v}`;
  return v;
