    const c = KPI_LIB.cats[r[0]];
    out.push({ key: awKey('kpi', i), kind: 'kpi', id: i, title: r[2], desc: `${r[3]} · ${c[0]}`, icon: '🔢', type: 'kpi', tag: KPI_LIB.mtypes[r[4]] });
